write_probe_matrix.command:
TESTDIR=/mnt/ntfs-disk python3 -c 'import json,os,pathlib,uuid;d=pathlib.Path(os.environ['"'"'TESTDIR'"'"']);p=d/('"'"'csrm_file_probe_'"'"'+uuid.uuid4().hex);r={'"'"'directory'"'"':str(d),'"'"'exists'"'"':d.exists(),'"'"'is_dir'"'"':d.is_dir()};
try:
    f=open(p,'"'"'wb'"'"'); f.write(b'"'"'probe\n'"'"'); f.flush(); os.fsync(f.fileno()); f.close();    p.unlink(); r.update({'"'"'ok'"'"':True})
except OSError as exc:
    r.update({'"'"'ok'"'"':False,'"'"'errno'"'"':exc.errno,'"'"'error'"'"':str(exc)})
print(json.dumps(r,sort_keys=True))'

